func isValidBST(root *TreeNode) bool {
	var validate func(node *TreeNode, min, max int64) bool
	validate = func(node *TreeNode, min, max int64) bool {
		if node == nil {
			return true
		}
		if int64(node.Val) <= min || int64(node.Val) >= max {
			return false
		}
		return validate(node.Left, min, int64(node.Val)) && validate(node.Right, int64(node.Val), max)
	}
	return validate(root, math.MinInt64, math.MaxInt64)
}

class TreeNode {
  int val;
  TreeNode left;
  TreeNode right;

  TreeNode(int x) {
    val = x;
  }
}

class Solution {
  private boolean validate(TreeNode node, long min, long max) {
    if (node == null) return true;
    if (node.val <= min || node.val >= max) return false;
    return validate(node.left, min, node.val) && validate(node.right, node.val, max);
  }

  public boolean isValidBST(TreeNode root) {
    return validate(root, Long.MIN_VALUE, Long.MAX_VALUE);
  }
}

class Solution:
    def isValidBST(self, root: Optional[TreeNode]) -> bool:
        def validate(node, low, high):
            if node is None:
                return True
            if not (low < node.val < high):
                return False
            return validate(node.left, low, node.val) and validate(node.right, node.val, high)

        return validate(root, float("-inf"), float("inf"))

impl Solution {
  pub fn is_valid_bst(root: Option<Box<TreeNode>>) -> bool {
    fn validate(node: &Option<Box<TreeNode>>, min: i64, max: i64) -> bool {
      match node {
        None => true,
        Some(n) => {
          let v = n.val as i64;
          v > min && v < max && validate(&n.left, min, v) && validate(&n.right, v, max)
        }
      }
    }
    validate(&root, i64::MIN, i64::MAX)
  }
}

const isValidBST = (root: TreeNode | null): boolean => {
  const validate = (node: TreeNode | null, min: number, max: number): boolean => {
    if (!node) return true;
    if (node.val <= min || node.val >= max) return false;
    return validate(node.left, min, node.val) && validate(node.right, node.val, max);
  };
  return validate(root, -Infinity, Infinity);
};
